export class Diagnostics {
    constructor() {
        this.list = [];
        this.seen = new Set();
    }
    add(diagnostic) {
        const key = `${diagnostic.level}|${diagnostic.code}|${diagnostic.pkg ?? ''}|${diagnostic.message}`;
        if (this.seen.has(key))
            return;
        this.seen.add(key);
        this.list.push(diagnostic);
    }
    error(code, message, pkg) {
        this.add(withPkg({ level: 'error', code, message }, pkg));
    }
    warn(code, message, pkg) {
        this.add(withPkg({ level: 'warning', code, message }, pkg));
    }
    addAll(diagnostics) {
        for (const d of diagnostics)
            this.add(d);
    }
    hasErrors() {
        return this.list.some((d) => d.level === 'error');
    }
}
function withPkg(d, pkg) {
    return pkg === undefined ? d : { ...d, pkg };
}
export function hasErrors(diagnostics) {
    return diagnostics.some((d) => d.level === 'error');
}
